            aOrbiterA = (((aWandererC + RotL64(aScatter, 43U)) + RotL64(aCarry, 35U)) + 0xA3180B5AA326765FULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 18U)) & S_SALT1];
