            aOrbiterK = ((aWandererC + RotL64(aPrevious, 21U)) + RotL64(aCarry, 53U)) + 0xB828AC6DB68A7156ULL;
            aOrbiterB = (aWandererI + RotL64(aCross, 28U)) + 0x3C3E288D7017D3D8ULL;
            aOrbiterC = (((aWandererF + RotL64(aIngress, 43U)) + RotL64(aCarry, 3U)) + 0xB76A8A693719120AULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 29U)) & S_SALT1];
