            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0x0295269F7260F72BULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0x9F67D25C256C823AULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 26U)) & S_SALT1];
