            //
            aOrbiterB = ((aOrbiterB + aOrbiterG) + 0xEA55DB5F66EA4654ULL) + aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0xBA7378B5887B8343ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x50E76BC87854496BULL), 47U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x1BDC7247EBCB7BC5ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0xA4DAEC4FE983E528ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xE10254A1BAC1D8A3ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xB55CB334D5A3791CULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0xBDA2C545234D3FA1ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xA6DBB863DF947405ULL), 29U);
            //
            aIngress = aOrbiterI ^ RotL64(aOrbiterC, 29U);
