            aWandererD = aWandererD + (((RotL64(aPrevious, 21U) + aOrbiterC) + RotL64(aOrbiterI, 22U)) + aKeyRotateWandererUpdateSaltC[((aIndex + 11U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aIngress, 47U) + RotL64(aOrbiterG, 35U)) + aOrbiterC);
