            aIngress = (RotL64(aShadowLaneA[((aIndex + 11182U)) & S_BLOCK1], 19U) ^ RotL64(aPoisonLaneC[((aIndex + 9454U)) & S_BLOCK1], 29U));
            aIngress ^= (RotL64(aPlasmaLaneD[((aIndex + 11321U)) & S_BLOCK1], 37U) ^ RotL64(aSoilLaneA[((aIndex + 14492U)) & S_BLOCK1], 48U));
