            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 14722U)) & S_BLOCK1], 21U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 13103U)) & S_BLOCK1], 42U));
            aCross ^= (RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 8946U)) & S_BLOCK1], 5U) ^ RotL64(aWoodLaneB[((S_BLOCK1 - aIndex + 14356U)) & S_BLOCK1], 57U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aIngress, 41U) ^ RotL64(aCarry, 5U)) + (RotL64(aPrevious, 56U) + RotL64(aCross, 19U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterG = (((aWandererE + RotL64(aIngress, 27U)) + RotL64(aCarry, 29U)) + 0x8C4E6D46CDC06446ULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 10U)) & S_SALT1];
            aOrbiterD = ((aWandererK + RotL64(aScatter, 41U)) + RotL64(aCarry, 13U)) + 0x0CBD4A39BC0EA13CULL;
            aOrbiterF = ((aWandererJ + RotL64(aPrevious, 3U)) + RotL64(aCarry, 53U)) + 0x860D2E613E331ADDULL;
            aOrbiterK = (aWandererB + RotL64(aCross, 21U)) + 0xAF57979A088933DFULL;
            aOrbiterE = (aWandererC + RotL64(aScatter, 11U)) + 0x8CCB78DC9D0E0ADFULL;
            aOrbiterB = (aWandererI + RotL64(aPrevious, 47U)) + 0x88514778538F4C62ULL;
            aOrbiterJ = ((aWandererH + RotL64(aIngress, 54U)) + 0xD921CE13E6711B21ULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 25U)) & S_SALT1];
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0xC25A93C2939EC2A6ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x2AA71789D13703D2ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x101DFB832EBAB95DULL), 19U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x14B0BBEBE0F31F7EULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0xBC886314C7D05795ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1EC47843F46B18B9ULL), 5U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x437134FAB5AEF4D3ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x10962D08980ED60FULL;
            aOrbiterK = RotL64((aOrbiterK * 0x141B1A246E571DC3ULL), 13U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0xEF3DA2F1E2AB9DB6ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterE) ^ 0x89231345B23D65C3ULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 16U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x8C0757605AA98D99ULL), 27U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x313016A3123B2CC5ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0x43F20E82E02586F6ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xA9B0587667F561B9ULL), 39U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0x318D5E98B94BFA3DULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x2161F227D4EEE684ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x275AE29E46AB62EFULL), 51U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0xE199329EF1FDDABDULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 4U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0xAEAC34A9267C2D2CULL;
            aOrbiterG = RotL64((aOrbiterG * 0xC684AB5B6F061977ULL), 57U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterE, 37U);
