            aWandererJ = aWandererJ + ((RotL64(aScatter, 11U) + aOrbiterJ) + RotL64(aOrbiterD, 19U));
            aWandererE = aWandererE ^ (((RotL64(aCross, 47U) + RotL64(aOrbiterK, 53U)) + aOrbiterG) + aKeyRotateWandererUpdateSaltA[(((31U - aIndex) + 13U)) & S_SALT1]);
            aWandererI = aWandererI + ((((RotL64(aIngress, 3U) + RotL64(aOrbiterB, 46U)) + aOrbiterG) + RotL64(aCarry, 29U)) + aKeyRotateWandererUpdateSaltB[((aIndex + 9U)) & S_SALT1]);
