            aOrbiterK = (aWandererA + RotL64(aScatter, 41U)) + 0xDDBE2F79D562A9F8ULL;
            aOrbiterJ = ((aWandererB + RotL64(aIngress, 60U)) + 0x1737C2C581729994ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterA = ((aWandererF + RotL64(aCross, 5U)) + RotL64(aCarry, 53U)) + 0x2AAD98FA448E4F32ULL;
