            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x24AA935367D90356ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0x180B89E78E76CE41ULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x2AC2920AC4E50917ULL), 35U);
