            //
            aOrbiterD = ((aOrbiterD + aOrbiterJ) + 0xA5A72A79A782EEEAULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 3U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xE6BD3FBB5C91DA19ULL;
