            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0x9C468A589470A56DULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x0A2C6C81DBE129C3ULL;
