            //
            aOrbiterK = ((aOrbiterK + aOrbiterA) + 0xF45221D397F44D67ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0x31EDE575960619BCULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
