            aOrbiterH = (((aWandererH + RotL64(aIngress, 29U)) + RotL64(aCarry, 39U)) + 0x59D40CF85DD85D8EULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 22U)) & S_SALT1];
