            aOrbiterC = (((aWandererB + RotL64(aScatter, 21U)) + RotL64(aCarry, 51U)) + 0x68BCE39E0BCFB2FBULL) + aKeyRotateOrbiterAssignSaltB[((aIndex + 16U)) & S_SALT1];
