            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aIngress, 23U) ^ RotL64(aCross, 11U)) ^ (RotL64(aPrevious, 37U) + RotL64(aCarry, 52U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterE = (aWandererD + RotL64(aPrevious, 39U)) + 0xB4FD2B8EAAF9EC27ULL;
            aOrbiterC = (aWandererH + RotL64(aIngress, 11U)) + 0xB87A0862194B012FULL;
            aOrbiterK = ((aWandererK + RotL64(aCross, 3U)) + RotL64(aCarry, 41U)) + 0xE27491472611A0C7ULL;
            aOrbiterI = (aWandererC + RotL64(aScatter, 54U)) + 0xB07E6EA7252CF33EULL;
