            aWandererJ = aWandererJ + (((RotL64(aIngress, 51U) + aOrbiterJ) + RotL64(aOrbiterI, 21U)) + aKeyRotateWandererUpdateSaltE[((aIndex + 6U)) & S_SALT1]);
            //
