            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x386F332F2D7E8D6BULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterJ) ^ 0x6DCDCD5F2AC1753EULL) ^ aKeySpawnOrbiterUpdateSaltE[((aIndex + 8U)) & S_SALT1];
